r\n","GO\r\n","create procedure [dbo].[sp_delete_Table_Reservations]\r\n@ReservationId int\r\nas\r\nbegin\r\ndelete from Table_Reservations \r\nwhere ReservationId=@ReservationId\r\nend\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_delete_Table_Reservations' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_insert_into_Table_Customer]"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_insert_into_Table_Customer' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_insert_into_Table_Customer]    Script Date: 5.05.2026 20:08:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE procedure [dbo].[sp_insert_into_Table_Customer]\r\n\t@FirstName nvarchar(50),\r\n\t@LastName nvarchar(50),\r\n\t@TurkishIdentityNumber nvarchar(11),\r\n\t@PhoneNumber nvarchar(15)\r\nas\r\nbegin\r\n\tinsert into\r\n\tUsers(\r\n\tFirstName,LastName,TurkishIdentityNumber,PhoneNumber)\r\n\tvalues(@FirstName, @LastName, @TurkishIdentityNumber, @PhoneNumber)\r\nend\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_insert_into_Table_Customer' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_insert_into_Table_Reservations]"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_insert_into_Table_Reservations' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_insert_into_Table_Reservations]    Script Date: 5.05.2026 20:08:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE procedure [dbo].[sp_insert_into_Table_Reservations]\r\n@UserId int,\r\n@FieldId int,\r\n@ReservationDate date,\r\n@time_id int,\r\n@city_id tinyint\r\nas\r\nbegin\r\ninsert into Table_Reservations(UserId,FieldId,ReservationDate,time_id,city_id)\r\nvalues (@UserId,@FieldId,@ReservationDate,@time_id,@city_id)\r\nend\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_insert_into_Table_Reservations' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_select_Table_Customer]"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_select_Table_Customer' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_select_Table_Customer]    Script Date: 5.05.2026 20:08:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","create procedure [dbo].[sp_select_Table_Customer]\nAS\nBEGIN\nSelect UserId as 'Kullanıcı ID',\n\t   FirstName as 'Kullanıcı Adı',\n\t   LastName as 'Kullanıcı Soyadı',\n\t   TurkishIdentityNumber as 'Müşteri TCKN',\n\t   PhoneNumber as 'Müşteri Tel. No'\nFROM Users\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_select_Table_Customer' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_select_Table_Reservations]"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_select_Table_Reservations' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_select_Table_Reservations]    Script Date: 5.05.2026 20:08:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE procedure [dbo].[sp_select_Table_Reservations]\r\nas \r\nbegin\r\nselect tr.ReservationId as 'Rezervasyon ID',\r\n\t   tu.FirstName as 'Adı',\r\n\t   tu.LastName as 'Soyadı',\r\n\t   tu.PhoneNumber as 'Tel No',\r\n\t   tc.city_name as 'Şehir',\r\n\t   tff.FieldName as 'Halı Saha Adı',\r\n\t   tr.ReservationDate as 'Tarihi',\r\n\t   tt.times as 'Saati',\r\n\t   tp.PaymentAmount as 'Fiyat'\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nfrom Table_Reservations tr inner join Users tu on tu.UserId = tr.UserId \r\ninner join Table_FootballFields tff on tff.FieldId = tr.FieldId \r\ninner join Table_Cities tc on tc.city_id=tff.city_id \r\ninner join Table_Time tt on tr.time_id=tt.time_id\r\ninner join Table_Payments tp on tp.PaymentId=tt.PaymentId\r\nend\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_select_Table_Reservations' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_update_Table_Customer]"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_update_Table_Customer' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_update_Table_Customer]    Script Date: 5.05.2026 20:08:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","create procedure [dbo].[sp_update_Table_Customer]\r\n\r\n\t@UserId int,\r\n\t@FirstName nvarchar(50),\r\n\t@LastName nvarchar(50),\r\n\t@TurkishIdentityNumber nvarchar(11),\r\n\t@PhoneNumber nvarchar(15)\r\nas\r\nbegin\r\n\tupdate Users set\r\n\tFirstName = @FirstName,\r\n\tLastName = @LastName,\r\n\tTurkishIdentityNumber = @TurkishIdentityNumber,\r\n\tPhoneNumber = @PhoneNumber\r\n\twhere\r\n\tUserId = @UserId\r\nend\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_update_Table_Customer' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_update_Table_Reservations]"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_update_Table_Reservations' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_update_Table_Reservations]    Script Date: 5.05.2026 20:08:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE procedure [dbo].[sp_update_Table_Reservations]\r\n@ReservationId int,\r\n@UserId int,\r\n@FieldId int,\r\n@ReservationDate date,\r\n@time_id int,\r\n@city_id tinyint\r\nas\r\nbegin\r\nupdate Table_Reservations set\r\nUserId=@UserId,\r\nFieldId=@FieldId,\r\nReservationDate=@ReservationDate,\r\ntime_id=@time_id,\r\ncity_id=@city_id\r\nwhere ReservationId=@ReservationId\r\nend\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']/StoredProcedure[@Name='sp_update_Table_Reservations' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [HalıSahaTakip]"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']","object_type":"Database"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["USE [master]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']","object_type":"Database"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER DATABASE [HalıSahaTakip] SET  READ_WRITE \r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='Resul']/Database[@Name='HalıSahaTakip']","object_type":"Database"}}]}